public Character convertToType(Class<?> type, Object value) throws Exception {
    if (type.equals(Character.class) || type.equals(char.class)) {
        if (value instanceof Character) {
            return (Character) value;
        } else if (value instanceof String) {
            String str = (String) value;
            if (str.length() > 0) {
                return str.charAt(0);
            }
        } else if (value instanceof Number) {
            return (char) ((Number) value).byteValue();
        } else {
            throw new IllegalArgumentException("Cannot convert input value of type " + value.getClass().getName() + " to a Character");
        }
    } else {
        throw new IllegalArgumentException("Cannot convert input value to a Character");
    }
}

