private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Intialize the circulator to start at the given node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // Traverse the component using the given direction
    while (circulator.next() != stop) {
        // If the current node satisfies the predicate, return the circulator
        if (predicate.test(circulator.getNode())) {
            return circulator;
        }
    }

    // If the circulator reached the stop node and no node satisfying the predicate was found, return null
    return null;
}

