	// Initialize variables
	long suffixSum = 0;
	long totalSum = 0;
	List<Integer> suffixSumList = new ArrayList<>();

	// Iterate through the list in reverse order
	for (int i = bounds.size() - 1; i >= 0; i--) {
		// Add the current element to the suffix sum
		suffixSum += bounds.get(i);

		// Add the current element to the total sum
		totalSum += bounds.get(i);

		// Add the suffix sum to the list
		suffixSumList.add((int) suffixSum);
	}

	// Return the computed suffix sum list and the total sum
	return new Pair<>(suffixSumList, totalSum);
}

