    // Compute the maximum lower bound for every key
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int lowerBound = 0;
        for (int j = i - 1; j >= 0; j--) {
            K otherKey = keys.get(j);
            if (key.compareTo(otherKey) < 0) {
                lowerBound++;
            } else {
                break;
            }
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
