    int remaining = bb.remaining();
    while (i < remaining) {
        if (bb.get(i) >= 0) {
            // value is less than 128, which means it is a single octet
            sb.append((char) bb.get(i));
            i++;
        } else {
            // value is greater than 127, which means it is a multi-octet sequence
            int octetCount = 1;
            switch (bb.get(i) & 0xff) {
                case 0b110_xxxx_xxxx:
                    octetCount = 2;
                    break;
                case 0b1110_xxxx_xxxx:
                    octetCount = 3;
                    break;
                case 0b1111_0xxx_xxxx:
                    octetCount = 4;
                    break;
                case 0b1111_10xx_xxxx:
