    // UTF-8 decoding
    int count = 0;
    int firstOctet = bb.get(i) & 0xFF;
    if (firstOctet <= 0x7F) {
        // 1-byte character
        sb.append((char) firstOctet);
        count = 1;
    } else if (firstOctet >= 0xC0 && firstOctet <= 0xDF) {
        // 2-byte character
        if (bb.remaining() >= 1) {
            int secondOctet = bb.get(i + 1) & 0xFF;
            if ((secondOctet & 0xC0) == 0x80) {
                sb.append((char) (((firstOctet & 0x1F) << 6) | (secondOctet & 0x3F)));
                count = 2;
            }
        }
    } else if (firstOctet >= 0xE0 && firstOctet <= 0xEF) {
        // 3-byte character
        if (bb.remaining() >= 2) {
            int secondOctet = bb.get(i + 1) & 0xFF;
            if ((secondOctet & 0xC0) == 0x80) {
                int thirdOctet = bb.get(i + 2) & 0xFF;
                if ((thirdOctet & 0xC0) == 0x80) {
                    sb.append((char) (((firstOctet & 0x0F) << 12) | ((secondOctet & 0x3F) << 6) | (thirdOctet & 0x3F)));
                    count = 3;
                }
            }
        }
    }
    return i + count;
