public static void addToClassPath(Vector<URL> cpV, String dir) {
    URL[] urls = new URL[0]; // Initialize an array of URLs
    try {
        // Get an array of jar files in the directory
        File[] files = new File(dir).listFiles();
        for (File file : files) {
            if (file.getName().endsWith(".jar")) {
                urls = Arrays.copyOf(urls, urls.length + 1); // Increase the size of the array
                urls[urls.length - 1] = file.toURI().toURL(); // Add the URL of the jar file to the array
            }
        }
        // Add the URLs to the classpath
        cpV.addAll(Arrays.asList(urls));
    } catch (MalformedURLException e) {
        e.printStackTrace();
    }
}

