public static Meteor lookup(HttpServletRequest r) {
  // Check if the HttpServletRequest has a Meteor as an attribute
  if (r.getAttribute("METEOR") != null) {
    return (Meteor) r.getAttribute("METEOR");
  }

  // Check if there is a Meteor in the session
  HttpSession session = r.getSession();
  if (session != null) {
    Object obj = session.getAttribute("METEOR");
    if (obj != null && obj instanceof Meteor) {
      return (Meteor) obj;
    }
  }

  // Check if there is a Meteor in the application scope
  ServletContext context = r.getServletContext();
  if (context != null) {
    Object obj = context.getAttribute("METEOR");
    if (obj != null && obj instanceof Meteor) {
      return (Meteor) obj;
    }
  }

  return null;
}

