public static String format(LoggingEvent event) {

    // determine the log level and color for the log message
    Level logLevel = event.getLevel();
    String color = "grey";
    if (logLevel == Level.ERROR || logLevel == Level.WARN) {
      color = "red";
    } else if (logLevel == Level.INFO) {
      color = "blue";
    }

    // construct the log message
    String message = event.getMessage();
    Throwable throwable = event.getThrowable();
    StringBuilder logMessage = new StringBuilder();
    logMessage.append("[").append(event.getLevel()).append("] ");
    logMessage.append("[").append(event.getLogger()).append("] ");
    logMessage.append(message);
    if (throwable != null) {
      logMessage.append("\n").append(throwable);
    }

    // add the log message and color to the writer
    String logString = logMessage.toString();
    AnsiConsole.out.println(Ansi.ansi().fg(color).a(logString).reset().toString());
  }

