public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int i = index;
    int utf8Size = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            utf8Size++;
        } else if (c <= 0x7FF) {
            utf8Size += 2;
        } else if (Character.isSurrogate(c)) {
            utf8Size += 4;
            i++;
        } else {
            utf8Size += 3;
        }
        i++;
    }
    return utf8Size;
}

