public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    // Calculate the total content size of the buffer
    int totalContentSize = 0;

    // Iterate through the nodes and write their contents to the output
    for (LinkedBuffer node : node) {
        // Get the next node in the list
        LinkedBuffer nextNode = node.getNext();

        // Write the current node's contents to the output
        out.writeInt(node.getContent());

        // Update the total content size
        totalContentSize += node.getContent().length;
    }

    return totalContentSize;
}

